 for p in ['drone','quad']:
  for t in ['feedback','no_feedback']:
   a=st[p][t]['preference_only'];b=st[p][t]['keep_selected'];lines.append(f"|{p}/{t}|{a['n']}|{a['gain_vs_source_pp']:.6f}|{b['gain_vs_source_pp']:.6f}|{a['worsened']}→{b['worsened']}|{a['query_changes']}→{b['query_changes']}|")
 lines+=['','Drone无反馈损害减少但没有消失：96条均值从−1.996702pp变为−0.623779pp，恶化22→12。反馈8条仍有明显收益。Quad无反馈收益没有被全部压回frozen，反而从+0.886580pp到+1.567943pp，恶化2→1。保持项不是将所有输出强制恢复source。','','相对log-odds输出漂移MSE，Drone从36.096783降为1.127181，Quad从30.409620降为0.372177。这是约束落实证据，不能替代任务指标。没有测Waymo源域，不能宣称源域遗忘已经发生或被解决。','','A208同反馈直接不更新对照仍保留：','','|方法|Drone mIoU|Quad mIoU|均值|','|---|---:|---:|---:|']
